"""Best pipeline found by TPOT (generated by Notebooks/tpot_test.ipynb — do not edit by hand).

Refits the pipeline on all labelled data (Datasets/train_processed.csv) and writes
Submissions/tpot_submission.csv for the Kaggle test set.

Usage:  python tpot_best_pipeline.py
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT / "src"))

import numpy as np
import pandas as pd
from sklearn.ensemble import GradientBoostingClassifier
from sklearn.feature_selection import SelectPercentile, f_classif
from sklearn.pipeline import make_pipeline
from tpot.export_utils import set_param_recursive
from sklearn.pipeline import Pipeline
from churn_utils import load_data, load_kaggle_test, make_tpot_encoder, SUBMISSION_DIR

exported_pipeline = make_pipeline(
    SelectPercentile(score_func=f_classif, percentile=53),
    GradientBoostingClassifier(learning_rate=0.1, max_depth=4, max_features=0.35000000000000003, min_samples_leaf=15, min_samples_split=8, n_estimators=100, subsample=0.5)
)
# Fix random state for all the steps in exported pipeline
set_param_recursive(exported_pipeline.steps, 'random_state', 42)

if __name__ == "__main__":
    X, y = load_data()
    ids, X_kaggle = load_kaggle_test()
    model = Pipeline([("encoder", make_tpot_encoder()), ("tpot", exported_pipeline)])
    model.fit(X, y)
    out = SUBMISSION_DIR / "tpot_submission.csv"
    pd.DataFrame({"id": ids, "Exited": model.predict_proba(X_kaggle)[:, 1]}).to_csv(out, index=False)
    print("Saved", out)
